<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driver\Rest\PlatformIdentityAllowController;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driver\Rest\PlatformIdentityListController;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driver\Rest\PlatformIdentityCreateController;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driver\Rest\PlatformIdentityRetrieveController;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driver\Rest\PlatformIdentityUpdateController;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driver\Rest\PlatformIdentityDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Service\Visibility\PlatformIdentityRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Usecase\Create\PlatformIdentityCreateAllowDecision;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Usecase\Update\PlatformIdentityUpdateAllowDecision;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Usecase\Retrieve\PlatformIdentityRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Usecase\List\PlatformIdentityListAllowDecision;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Access\PlatformIdentity\Application\Usecase\Delete\PlatformIdentityDeleteAllowDecision;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driven\PlatformIdentityReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\PlatformIdentity\Infrastructure\Driven\PlatformIdentityWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityReadGateway;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\Gateway\PlatformIdentityWriteGateway;

class PlatformIdentityPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[PlatformIdentityReadGateway::class] = \DI\autowire(PlatformIdentityReadRepositoryAdapter::class);
        $def[PlatformIdentityWriteGateway::class] = \DI\autowire(PlatformIdentityWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/platform-identity', [$this, 'setRoutesForPlatformIdentity']);
        $collector->group('/api/me/acl/access/platform-identity', [$this, 'setRoutesForPlatformIdentityAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(PlatformIdentityRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(PlatformIdentityCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(PlatformIdentityUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(PlatformIdentityRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(PlatformIdentityListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(PlatformIdentityDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("platform-identity", "list", "READ");
            $handler->registerResourceAction("platform-identity", "create", "WRITE");
            $handler->registerResourceAction("platform-identity", "retrieve", "READ");
            $handler->registerResourceAction("platform-identity", "update", "WRITE");
            $handler->registerResourceAction("platform-identity", "delete", "WRITE");

            $handler->registerResourceAttribute("platform-identity", "user", "MANAGE");
            $handler->registerResourceAttribute("platform-identity", "relyingParty", "MANAGE");
            $handler->registerResourceAttribute("platform-identity", "trustedClient", "MANAGE");
            $handler->registerResourceAttribute("platform-identity", "roles", "MANAGE");
            $handler->registerResourceAttribute("platform-identity", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForPlatformIdentityAcl(RouteCollectorProxy $platformIdentityGroup): void
    {
        $platformIdentityGroup->get('', [PlatformIdentityAllowController::class, 'genericAllow']);
        $platformIdentityGroup->get('/{uid}', [PlatformIdentityAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForPlatformIdentity(RouteCollectorProxy $platformIdentityGroup): void
    {
        $platformIdentityGroup->get('', [PlatformIdentityListController::class, 'list']);
        $platformIdentityGroup->post('', [PlatformIdentityCreateController::class, 'create']);
        $platformIdentityGroup->get('/{uid}', [PlatformIdentityRetrieveController::class, 'retrieve']);
        $platformIdentityGroup->put('/{uid}', [PlatformIdentityUpdateController::class, 'update']);
        $platformIdentityGroup->delete('/{uid}', [PlatformIdentityDeleteController::class, 'delete']);
        $platformIdentityGroup->delete('', [PlatformIdentityDeleteController::class, 'deleteAllForQuery']);
        $platformIdentityGroup->get('/~/delete-status/{uid}', [PlatformIdentityDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
